content.query:
let Targets = print Selected=pack_array({Machines}) | mv-expand Selected to typeof(string) | where Selected startswith '/subscriptions/' | project Key=tolower(Selected);
let HB = Heartbeat | where _ResourceId in~ ({Machines}) | summarize LastHeartbeat=max(TimeGenerated) by Key=tolower(_ResourceId);
let Performance = union isfuzzy=true Perf, (datatable(TimeGenerated:datetime, _ResourceId:string, ObjectName:string, CounterName:string, InstanceName:string, CounterValue:real) [])
| where TimeGenerated >= ago(5m) and _ResourceId in~ ({Machines})
| summarize CPU=avgif(CounterValue, ObjectName =~ 'Processor Information' and CounterName =~ '% Processor Time' and InstanceName =~ '_Total'), FreeMiB=avgif(CounterValue, ObjectName =~ 'Memory' and CounterName =~ 'Available Bytes') / 1048576.0 by Key=tolower(_ResourceId);
let Events = union isfuzzy=true Event, (datatable(_ResourceId:string) []) | where _ResourceId in~ ({Machines}) | summarize Events=count() by Key=tolower(_ResourceId);
Targets
| join kind=leftouter HB on Key
| join kind=leftouter Performance on Key
| join kind=leftouter Events on Key
| extend Minutes=tolong((now()-LastHeartbeat)/1m)
| extend Situation=case(Minutes >= 10 or CPU >= 80.0 or FreeMiB < 512.0, '要確認', isnull(LastHeartbeat) or isnull(CPU) or isnull(FreeMiB) or isnan(CPU) or isnan(FreeMiB), '未受信あり', '目安内')
| project ['マシン']=tostring(split(Key, '/')[-1]), ['リソースグループ']=tostring(split(Key, '/')[4]), ['種類']=iff(Key contains '/microsoft.hybridcompute/', 'Arc', 'Azure VM'), ['確認状況']=Situation, ['最終 Heartbeat']=LastHeartbeat, ['経過分']=Minutes, ['CPU (%)']=iff(isnan(CPU), real(null), round(CPU, 1)), ['空きメモリ (MiB)']=iff(isnan(FreeMiB), real(null), round(FreeMiB, 0)), ['Event 件数']=coalesce(Events, tolong(0))
| order by ['マシン'] asc
